/** Independent source-level execution. No annual generator/model import. */
import assert from "node:assert/strict";
import {legacy2018HeapReview as review} from "./legacy-2018-pm-heap-review";
export function heapParent(i:number){assert(Number.isInteger(i)&&i>0);return Math.floor((i-1)/2);}
const read=(a:number[],i:number)=>{assert(Number.isInteger(i)&&i>=0&&i<a.length&&Number.isInteger(a[i]),`undefined heap[${i}]`);return a[i];};
export function makeHeapReference(data:number[],aChoice=1,bChoice=3){assert(data.length>0);const heap:number[]=[];for(let i=0;i<data.length;i++){heap[i]=data[i];let k=i,guard=0;while(k>0){assert(++guard<=data.length);const index=[2*k+1,heapParent(k),2*k+2,2*k+1,heapParent(k),2*k+2][aChoice],condition=aChoice<3?read(heap,k)>read(heap,index):read(heap,k)<read(heap,index);if(!condition)break;const j=bChoice===0?read(heap,data.length-1):bChoice===1?read(heap,k):bChoice===2?heapParent(data.length-1):heapParent(k);const old=read(heap,k);heap[k]=read(heap,j);heap[j]=old;k=heapParent(k);}}return heap;}
export function isMaxHeap(a:number[],last=a.length-1){return Array.from({length:last},(_,i)=>i+1).every(i=>a[heapParent(i)]>=a[i]);}
export function downHeapReference(a:number[],last:number){let n=0;const steps:{parent:number;left:number;right:number|null;chosen:number;swapped:boolean}[]=[];while(2*n+1<=last){const left=2*n+1,right=2*n+2<=last?2*n+2:null,tmp=right!==null&&a[left]<=a[right]?right:left,swapped=a[tmp]>a[n];steps.push({parent:n,left,right,chosen:tmp,swapped});if(!swapped)return steps;[a[n],a[tmp]]=[a[tmp],a[n]];n=tmp;}return steps;}
export function heapSortReference(data:number[]){const heap=makeHeapReference(data),initial=heap.slice(),passes:{last:number;afterSwap:number[];steps:ReturnType<typeof downHeapReference>;afterDown:number[]}[]=[];for(let last=data.length-1;last>0;last--){[heap[0],heap[last]]=[heap[last],heap[0]];const afterSwap=heap.slice(),steps=downHeapReference(heap,last-1);assert(isMaxHeap(heap,last-1));passes.push({last,afterSwap,steps,afterDown:heap.slice()});}assert.deepEqual(heap,data.slice().sort((a,b)=>a-b));return{initial,passes,sorted:heap};}
export function enumerateHeapSourceCountermodels(){let arrays=0;const valid=Array(24).fill(true),counterexamples:(number[]|null)[]=Array(24).fill(null);for(let length=1;length<=6;length++){const visit=(data:number[])=>{if(data.length<length){for(let n=0;n<3;n++)visit([...data,n]);return;}arrays++;for(let a=0;a<6;a++)for(let b=0;b<4;b++){const id=a*4+b;let ok=false;try{const heap=makeHeapReference(data,a,b);ok=isMaxHeap(heap)&&JSON.stringify(heap.slice().sort((a,b)=>a-b))===JSON.stringify(data.slice().sort((a,b)=>a-b));}catch{}if(!ok){valid[id]=false;counterexamples[id]??=data.slice();}}heapSortReference(data);};visit([]);}assert.equal(arrays,1092);assert.deepEqual(valid.flatMap((b,i)=>b?[i]:[]),[7]);return{arrays,validPairs:[[1,3]],counterexamples};}
export function sourceHeapOperation(){const heap=[...review.sourceHeap];[heap[0],heap[6]]=[heap[6],heap[0]];const afterSwap=heap.slice(),steps=downHeapReference(heap,5);return{afterSwap,steps,correct:[1,3,(review.originalChoices[2] as readonly string[]).indexOf(String(afterSwap[0])),1,steps.find(s=>s.swapped)!.chosen-1]};}
